  // /api/inbox/reply, both of which forward ids verbatim to the relay.
  d.threads=[{thread_id:'__glossary__',origin:'edit-timeline',question:'How to drive edit-timeline - tools, docs and the traps that cost the most',unread:false,answered:true,synthetic:true}].concat(Array.isArray(d.threads)?d.threads.filter(function(t){return t&&t.thread_id!=='__glossary__'}):[]);
  threads=d.threads||[];
  const n=d.unread||0;
  const b=document.getElementById('unread');
  b.textContent=n+' unread';b.className=n?'':'zero';
  // Answered is derived from a real reply turn existing, not from a header
  // claiming the thread is closed - two live threads claim answered with no
  // reply on them, so the header value cannot be trusted here.
  // Synthetic rows (the permanent glossary entry) are excluded from BOTH sides:
  // counting one would claim a customer thread that does not exist AND credit an
  // answer nobody gave. Measured 2026-08-20: the counter read 8/113 against 112
  // real threads until this filter existed.
  const real=threads.filter(t=>!t.synthetic);
  const ans=real.filter(t=>t.answered).length;
  const rz=document.getElementById('resolved');
  if(rz){rz.textContent=ans+'/'+real.length+' answered';rz.className=(real.length&&ans===real.length)?'done':'';}
  document.title=(n?'('+n+') ':'')+'Customer inbox \u2014 edit-timeline';
  document.getElementById('list').innerHTML=threads.length?threads.map(t=>
    '<div class="item'+(t.unread?' unread':'')+(t.thread_id===sel?' sel':'')+'" data-id="'+esc(t.thread_id)+'">'+
    '<div class="who"><span>'+esc(t.origin||'unknown')+'</span><span>'+(t.answered?'replied':'NO REPLY')+'</span></div>'+
    '<div class="q">'+esc((t.question||'').slice(0,110))+'</div></div>').join('')
    :'<div class="empty">No customer threads.</div>';
