    const inb=x.role==='using-agent';
    return '<div class="turn '+(inb?'inbound':'outbound')+'"><div class="meta">'+(inb?'FROM '+esc(t.origin||'customer'):'YOUR REPLY')+' \xB7 '+esc(x.ts||'')+'</div>'+esc(x.text||'')+'</div>';
